"""Build a local synchronized video / observed ROS event viewer (standard library only)."""
import argparse,json,subprocess
from pathlib import Path
from fractions import Fraction


def build(output):
    output=Path(output)
    frames=json.loads((output/'video-frames.json').read_text())
    trace=json.loads((output/'ros-events.json').read_text())
    result=json.loads((output/'result.json').read_text())
    if len(frames)<2:raise ValueError('at least two recorded physical frames required')
    delta=round(frames[1]['simulation_time_s']-frames[0]['simulation_time_s'],9)
    fps=1/Fraction(delta).limit_denominator(1000000)
    subprocess.run(['ffmpeg','-y','-loglevel','error','-framerate',str(fps),'-i',str(output/'frames'/'%06d.jpg'),
        '-c:v','libx264','-crf','20','-pix_fmt','yuv420p','-movflags','+faststart',str(output/'scenario.mp4')],check=True)
    metadata=dict(video_start_s=frames[0]['simulation_time_s'],frame_period_s=delta,frames=len(frames),
        events=len(trace['events']),result=result,topics=trace['topics'])
    (output/'timeline-metadata.json').write_text(json.dumps(metadata,indent=2))
    html=TEMPLATE.replace('__DATA__',json.dumps(dict(meta=metadata,events=trace['events']),ensure_ascii=False).replace('<','\\u003c'))
    (output/'dashboard.html').write_text(html)
    return output/'dashboard.html'


